def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_c = 0
    for x in me:
        if x == 'C':
            my_c += 1

    last_me = me[-1]
    last_opp = opp[-1]

    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    opp_rate = opp_c / float(n)

    recent_len = 20 if n >= 20 else n
    recent = opp[-recent_len:]
    recent_c = 0
    for x in recent:
        if x == 'C':
            recent_c += 1
    recent_rate = recent_c / float(recent_len)

    short_len = 8 if n >= 8 else n
    short = opp[-short_len:]
    short_c = 0
    short_d = 0
    for x in short:
        if x == 'C':
            short_c += 1
        else:
            short_d += 1

    def opp_streak_def():
        s = 0
        for x in reversed(opp):
            if x == 'D':
                s += 1
            else:
                break
        return s

    def opp_streak_coop():
        s = 0
        for x in reversed(opp):
            if x == 'C':
                s += 1
            else:
                break
        return s

    def last_k_all_def(k):
        if n < k:
            return False
        for i in range(n - k, n):
            if opp[i] != 'D':
                return False
        return True

    def last_k_all_coop(k):
        if n < k:
            return False
        for i in range(n - k, n):
            if opp[i] != 'C':
                return False
        return True

    dstreak = opp_streak_def()
    cstreak = opp_streak_coop()

    if n <= 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if opp_d == 0:
        if n >= 97:
            return 'D'
        if n >= 90 and rng.random() < 0.5:
            return 'D'
        if n >= 60 and opp_c >= n - 1 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if opp_c == 0:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if n >= 10 and opp_rate <= 0.15:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    if dstreak >= 3:
        if rng.random() < 0.10:
            return 'C'
        return 'D'

    if dstreak == 2:
        if recent_rate < 0.35:
            return 'D'
        if last_me == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if recent_rate > 0.55 and opp_rate > 0.55 and rng.random() < 0.25:
                return 'C'
            return 'D'
        if last_me == 'D':
            if recent_rate > 0.60 and rng.random() < 0.30:
                return 'C'
            if cstreak == 0 and rng.random() < 0.15:
                return 'C'
            return 'D'

    if cstreak >= 6 or last_k_all_coop(6):
        if n >= 96:
            if rng.random() < 0.90:
                return 'D'
            return 'C'
        if n >= 88 and rng.random() < 0.35:
            return 'D'
        if opp_rate > 0.90 and n >= 30 and rng.random() < 0.07:
            return 'D'
        return 'C'

    if recent_rate >= 0.80:
        if n >= 94:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        if n >= 85 and rng.random() < 0.20:
            return 'D'
        if opp_rate > 0.85 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if recent_rate >= 0.55:
        if last_me == 'D' and last_opp == 'C':
            if rng.random() < 0.80:
                return 'C'
            return 'D'
        if n >= 92:
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        return 'C'

    if recent_rate >= 0.30:
        if last_opp == 'C':
            if rng.random() < 0.65:
                return 'C'
            return 'D'
        return 'D'

    if recent_rate >= 0.15:
        if last_opp == 'C' and rng.random() < 0.40:
            return 'C'
        return 'D'

    if rng.random() < 0.08:
        return 'C'
    return 'D'
